import sys; sys.path.insert(0,"/app/analysis")
from load import meta, series
import datetime as dt, statistics, random
random.seed(7)
MASK={'STEAM_PRES_01':[(dt.datetime(2024,1,15,19,55),dt.datetime(2024,1,15,20,30))],
      'COOLING_PRES_01':[(dt.datetime(2024,1,16,0,5),dt.datetime(2024,1,16,0,40))]}
W0,W1=dt.datetime(2024,1,15,21,0),dt.datetime(2024,1,16,2,45)

def fit(xs,ys,tc):
    n=len(xs); c=[[1.0]*n,xs,[max(0.0,x-tc) for x in xs]]
    A=[[sum(c[i][k]*c[j][k] for k in range(n)) for j in range(3)] for i in range(3)]
    b=[sum(c[i][k]*ys[k] for k in range(n)) for i in range(3)]
    M=[A[i][:]+[b[i]] for i in range(3)]
    for i in range(3):
        p=max(range(i,3),key=lambda r:abs(M[r][i]))
        if abs(M[p][i])<1e-12: return 1e30
        M[i],M[p]=M[p],M[i]
        for r in range(3):
            if r!=i:
                f=M[r][i]/M[i][i]
                for cc in range(i,4): M[r][cc]-=f*M[i][cc]
    sol=[M[i][3]/M[i][i] for i in range(3)]
    return sum((ys[k]-(sol[0]+sol[1]*xs[k]+sol[2]*max(0.0,xs[k]-tc)))**2 for k in range(n))

data={}
for sid,m in meta.items():
    pts=[(t,v) for t,v in series[sid] if W0<=t<=W1 and not any(a<=t<=b for a,b in MASK.get(sid,[]))]
    data[sid]=([(t-W0).total_seconds()/60 for t,v in pts],[v for t,v in pts])

order_counts={}
for b in range(200):
