        xs,ys=data[sid]
        idx=[random.randrange(len(xs)) for _ in range(len(xs))]
        bx=[xs[i] for i in idx]; by=[ys[i] for i in idx]
        best=min(range(30,int(xs[-1])-20), key=lambda tc: fit(bx,by,tc))
        onsets.setdefault(m['subsystem'],[]).append(best-int(m['response_delay_minutes']))
    o=tuple(sorted(onsets,key=lambda s:statistics.median(onsets[s])))
    order_counts[o]=order_counts.get(o,0)+1
for o,c in sorted(order_counts.items(),key=lambda kv:-kv[1]):
    print(f"{c/2:5.1f}%  {' -> '.join(o)}")
