import sys; sys.path.insert(0,"/app/analysis")
from load import meta, series
import numpy as np, datetime as dt
rng=np.random.default_rng(7)
MASK={'STEAM_PRES_01':[(dt.datetime(2024,1,15,19,55),dt.datetime(2024,1,15,20,30))],
      'COOLING_PRES_01':[(dt.datetime(2024,1,16,0,5),dt.datetime(2024,1,16,0,40))]}
W0,W1=dt.datetime(2024,1,15,21,0),dt.datetime(2024,1,16,2,45)

def sse_scan(x,y,tcs):
    out=np.empty(len(tcs))
    for i,tc in enumerate(tcs):
        A=np.column_stack([np.ones_like(x),x,np.maximum(0,x-tc)])
        r=np.linalg.lstsq(A,y,rcond=None)[1]
        out[i]= r[0] if r.size else ((y-A@np.linalg.lstsq(A,y,rcond=None)[0])**2).sum()
    return out

D={}
for sid,m in meta.items():
    pts=[(t,v) for t,v in series[sid] if W0<=t<=W1 and not any(a<=t<=b for a,b in MASK.get(sid,[]))]
    D[sid]=(np.array([(t-W0).total_seconds()/60 for t,v in pts]),np.array([v for t,v in pts]))

tc_grid=np.arange(30, (W1-W0).total_seconds()/60-20)
counts={}
subs={}
for sid,m in meta.items(): subs.setdefault(m['subsystem'],[]).append(sid)

for b in range(500):
    on={}
    for sid,m in meta.items():
        x,y=D[sid]
        idx=rng.integers(0,len(x),len(x))
        bx,by=x[idx],y[idx]
        s=sse_scan(bx,by,tc_grid)
        on.setdefault(m['subsystem'],[]).append(tc_grid[np.argmin(s)]-int(m['response_delay_minutes']))
    o=tuple(sorted(on,key=lambda k:np.median(on[k])))
    counts[o]=counts.get(o,0)+1
tot=sum(counts.values())
for o,c in sorted(counts.items(),key=lambda kv:-kv[1]):
    print(f"{100*c/tot:6.2f}%  {' -> '.join(o)}")
